function setVisible(element, visible) {
  if (!element) return;
  element.classList.toggle('hidden', !visible);
}

function escapeHtml(text) {
  if (!text) return '';
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

